/**
 * Internationalization (i18n) translation dictionary and engine for GovernWorld.
 * Supports English (en), Spanish (es), French (fr), German (de), Japanese (ja),
 * Portuguese (pt), and Chinese (zh).
 */

export type LanguageCode = "en" | "es" | "fr" | "de" | "ja" | "pt" | "zh";
export type SupportedLanguage = LanguageCode;

export interface LanguageMeta {
  code: LanguageCode;
  name: string;
  nativeName: string;
}

export const SUPPORTED_LANGUAGES: LanguageMeta[] = [
  { code: "en", name: "English", nativeName: "English" },
  { code: "es", name: "Spanish", nativeName: "Español" },
  { code: "fr", name: "French", nativeName: "Français" },
  { code: "de", name: "German", nativeName: "Deutsch" },
  { code: "ja", name: "Japanese", nativeName: "日本語" },
  { code: "pt", name: "Portuguese", nativeName: "Português" },
  { code: "zh", name: "Chinese (Simplified)", nativeName: "简体中文" },
];

