    "howto_protection_title": "📘 Quick Guide: How to Scan & Protect a Page",
    "howto_protection_step1": "1. Choose a Compliance Preset (HIPAA, PCI-DSS, GDPR) or toggle any of the 24 detection categories below.",
    "howto_protection_step2": "2. Click Scan This Page (or press Alt+Shift+S) to inspect visible text, accessibility labels, and embedded images.",
    "howto_protection_step3": "3. Review masked previews in the Findings list, then click Apply Selected Masks or Copy Redacted Text.",
    "howto_doc_title": "📘 Step-by-Step: How to Redact a Document",
    "howto_doc_step1": "1. Upload or Drop a PDF (.pdf), Word (.docx), or Image (.png, .jpg, .webp) up to 20 MB.",
    "howto_doc_step2": "2. Review & Adjust boxes on each page thumbnail (or open Full-Screen Review). Use ✏️ Draw Box to add custom regions.",
    "howto_doc_step3": "3. Redact & Verify: Choose Blackout, Whiteout, or Text Stamp, then click Redact & Download.",
    "tool_save_location_rule": "📍 Learn Location Rule",
    "howto_logic_title": "📘 Step-by-Step: How to Create Custom Logic & Site Policies",
    "howto_logic_step1": "1. Personal Detection Logic: Click + Create Personal Logic and paste 2–5 positive examples.",
    "howto_logic_step2": "2. Test & Configure: Test against sample text, optional context cues, capture group, and length bounds.",
    "howto_logic_step3": "3. Site Policies: Click + Add Site Policy to configure per-domain rules or block paste on specific sites.",
    "howto_review_title": "📘 Step-by-Step: How to Verify Coverage & Export Audit Proofs",
    "howto_review_step1": "1. Check Scan Coverage: Inspect whether the last scan was Fully Scanned, Partially Scanned, or Blocked.",
    "howto_review_step2": "2. Review Recent Activity: Every scan, mask, and document redaction is recorded with counts only.",
    "howto_review_step3": "3. Export Signed Audit Log: Click Export Signed Audit Log to download an ECDSA P-256 signed JSONL proof.",
