    "howto_prot_step1_title": "1. Scan & Mask Webpages (Alt+Shift+S):",
    "howto_prot_step1_desc": "Click Scan This Page to detect 24 categories of PII, PHI, financial data, and secrets on-device. Review the Compliance Risk Scorecard, check or uncheck findings, then click Apply Masks (Alt+Shift+M) to cover values on the page, Copy Redacted for sanitized text, or Export (CSV/JSON).",
    "howto_prot_step2_title": "2. Guard AI Prompts & Forms (Paste Shield):",
    "howto_prot_step2_desc": "Active in This Tab after you open GovernWorld (or across all sites when Always On is enabled). Pasting sensitive text into ChatGPT, Claude, Slack, or forms opens an in-page shield where you can Sanitize & Paste, Paste Unchanged, or Cancel.",
    "howto_prot_step3_title": "3. Redact Documents Locally:",
    "howto_prot_step3_desc": "Drop a PDF, Word (.docx), or image below (up to 20 MB, 20 pages per pass). Toggle detected boxes or drag with Draw Box, pick Blackout/Whiteout/Stamp, and click Redact & Download for a pixel-verified flattened file.",
    "howto_doc_steps": "1. Click a box on any page thumbnail to toggle it, or drag with Draw Box to add custom regions. 2. Draw boxes on 3+ pages and click Learn Location Rule to save a reusable page-region detector. 3. Pick Blackout, Whiteout, or Text Stamp, then click Open full-screen review or Redact & Download.",
    "tool_save_location": "📍 Learn Location Rule",
    "howto_steps_badge": "Step-by-Step",
    "howto_logic_step1_title": "1. Personal Detection Wizard (4 Steps):",
    "howto_logic_step1_desc": "Click + Create Personal Logic → Step 1: Enter 2+ positive examples (or import a .txt/.csv file) and optional negative examples → Step 2: Pick a generated regex proposal → Step 3: Test live against sample text → Step 4: Set rule name, category, confidence, optional nearby Context Cues, and Min/Max length.",
    "howto_logic_step2_title": "2. Location-Aware Document Rules:",
    "howto_logic_step2_desc": "In Document Studio, draw boxes around a recurring field (such as a header ID) on at least 3 pages and click Learn Location Rule to save a normalized coordinate rule.",
    "howto_logic_step3_title": "3. Policy Studio (Website DLP Rules):",
    "howto_logic_step3_desc": "Click + Create Site Policy → pick a Quick Template (AI Chatbots, Health Portals, Dev & Secrets, Block Full Site) or type a domain (e.g. chatgpt.com) → choose data scope and action (Strict Block, Auto-Redact, or Warn).",
    "howto_audit_badge": "Verification",
    "howto_rev_step1_title": "1. Recent Protection Telemetry:",
    "howto_rev_step1_desc": "Shows cumulative findings detected, items masked or redacted, and pages/documents scanned across your local audit log.",
    "howto_rev_step2_title": "2. Honest Scan Coverage:",
    "howto_rev_step2_desc": "Green (✓) means every discovered region was inspected. Amber (!) or Red (✕) warns when cross-origin iframes, DRM media, or deferred images could not be inspected automatically.",
    "howto_rev_step3_title": "3. Signed Audit & Compliance Certificate:",
    "howto_rev_step3_desc": "Click Export Signed Audit below to download your ECDSA P-256 signed .jsonl log, .sig.json cryptographic proof, and printable HTML Compliance Certificate.",
    "disconnect_account_btn": "Disconnect account",
