    "howto_protection_title": "📘 Guía rápida: Cómo escanear y proteger una página",
    "howto_protection_step1": "1. Elige un perfil de cumplimiento (HIPAA, PCI-DSS, GDPR) o activa cualquiera de las 24 categorías.",
    "howto_protection_step2": "2. Haz clic en Escanear página (o Alt+Shift+S) para inspeccionar texto visible, etiquetas e imágenes.",
    "howto_protection_step3": "3. Revisa los hallazgos enmascarados y aplica máscaras visuales o copia el texto censurado.",
    "howto_doc_title": "📘 Paso a paso: Cómo censurar un documento",
    "howto_doc_step1": "1. Sube o arrastra un PDF (.pdf), Word (.docx) o imagen (.png, .jpg, .webp) de hasta 20 MB.",
    "howto_doc_step2": "2. Revisa y ajusta los cuadros en cada página o usa ✏️ Dibujar cuadro para añadir zonas manuales.",
    "howto_doc_step3": "3. Censura y verifica: Elige el estilo de censura y haz clic en Censurar y Descargar.",
    "tool_save_location_rule": "📍 Aprender regla de ubicación",
    "howto_logic_title": "📘 Paso a paso: Cómo crear lógica y políticas de sitio",
    "howto_logic_step1": "1. Lógica personal: Haz clic en + Crear lógica personal y pega de 2 a 5 ejemplos positivos.",
    "howto_logic_step2": "2. Prueba y configura: Prueba el patrón con texto de muestra, palabras clave de contexto y longitud.",
    "howto_logic_step3": "3. Políticas de sitio: Añade reglas por dominio para bloquear o advertir al pegar datos sensibles.",
    "howto_review_title": "📘 Paso a paso: Cómo verificar cobertura y exportar auditoría",
    "howto_review_step1": "1. Cobertura de escaneo: Verifica si el escaneo fue completo, parcial o bloqueado por el navegador.",
    "howto_review_step2": "2. Actividad reciente: Cada operación se registra localmente solo con conteos y marcas de tiempo.",
    "howto_review_step3": "3. Exportar registro firmado: Descarga un archivo JSONL firmado con ECDSA P-256 para cumplimiento.",
