    "howto_badge": "3 pasos",
    "howto_prot_step1_title": "1. Escanear y enmascarar páginas web (Alt+Shift+S):",
    "howto_prot_step1_desc": "Haz clic en Escanear página para detectar 24 categorías de PII, PHI, datos financieros y secretos en el dispositivo. Revisa los hallazgos y aplica máscaras o copia el texto censurado.",
    "howto_prot_step2_title": "2. Proteger prompts de IA y formularios (Escudo de pegado):",
    "howto_prot_step2_desc": "Activo en esta pestaña tras abrir GovernWorld (o en todos los sitios con Siempre activo). Al pegar datos sensibles en ChatGPT, Claude o formularios, puedes sanitizar, pegar sin cambios o cancelar.",
    "howto_prot_step3_title": "3. Censurar documentos localmente:",
    "howto_prot_step3_desc": "Arrastra un PDF, Word (.docx) o imagen abajo (hasta 20 MB, 20 páginas por pase). Ajusta los cuadros o dibuja zonas manuales y descarga una copia verificada.",
    "howto_doc_steps": "1. Haz clic en cualquier cuadro para activarlo o usa Dibujar cuadro. 2. Dibuja cuadros en 3+ páginas y pulsa Aprender regla de ubicación. 3. Elige el estilo y haz clic en Censurar y Descargar.",
    "tool_save_location": "📍 Aprender regla de ubicación",
    "howto_steps_badge": "Paso a paso",
    "howto_logic_step1_title": "1. Asistente de detección personal (4 pasos):",
    "howto_logic_step1_desc": "Haz clic en + Crear lógica personal → Paso 1: Ingresa 2+ ejemplos positivos → Paso 2: Elige un patrón sugerido → Paso 3: Prueba con texto de muestra → Paso 4: Define nombre, categoría, confianza y pistas de contexto.",
    "howto_logic_step2_title": "2. Reglas de ubicación en documentos:",
    "howto_logic_step2_desc": "En Document Studio, dibuja cuadros alrededor de un campo recurrente en al menos 3 páginas y pulsa Aprender regla de ubicación.",
    "howto_logic_step3_title": "3. Estudio de políticas (Reglas DLP por sitio):",
    "howto_logic_step3_desc": "Haz clic en + Crear política de sitio → elige una plantilla rápida o escribe un dominio → selecciona alcance y acción (Bloquear, Auto-censurar o Advertir).",
    "howto_audit_badge": "Verificación",
    "howto_rev_step1_title": "1. Telemetría de protección reciente:",
    "howto_rev_step1_desc": "Muestra el total acumulado de hallazgos detectados, elementos protegidos y páginas o documentos escaneados.",
    "howto_rev_step2_title": "2. Cobertura honesta de escaneo:",
    "howto_rev_step2_desc": "Verde (✓) indica inspección completa. Ámbar (!) o Rojo (✕) avisa cuando iframes de origen cruzado o medios diferidos no pudieron inspeccionarse.",
    "howto_rev_step3_title": "3. Auditoría firmada y certificado de cumplimiento:",
