    "howto_doc_step3": "3. Caviardez et vérifiez : Choisissez le style puis cliquez sur Caviarder et télécharger.",
    "tool_save_location_rule": "📍 Apprendre la règle de position",
    "howto_logic_title": "📘 Étape par étape : Créer une logique et des règles de site",
    "howto_logic_step1": "1. Logique personnelle : Cliquez sur + Créer une logique personnelle et collez 2 à 5 exemples.",
    "howto_logic_step2": "2. Testez et configurez : Testez sur un texte d'exemple avec mots-clés de contexte et longueur.",
    "howto_logic_step3": "3. Règles de site : Ajoutez des règles par domaine pour bloquer ou avertir lors du collage.",
