    "howto_badge": "3 étapes",
    "howto_prot_step1_title": "1. Scanner et masquer les pages web (Alt+Shift+S) :",
    "howto_prot_step1_desc": "Cliquez sur Scanner la page pour détecter 24 catégories de PII, PHI, données financières et secrets sur l'appareil. Vérifiez les résultats puis appliquez les masques ou copiez le texte caviardé.",
    "howto_prot_step2_title": "2. Protéger les prompts IA et formulaires (Bouclier de collage) :",
    "howto_prot_step2_desc": "Actif dans cet onglet après ouverture de GovernWorld (ou sur tous les sites avec Toujours actif). Lors d'un collage sensible dans ChatGPT, Claude ou un formulaire, nettoyez, collez tel quel ou annulez.",
    "howto_prot_step3_title": "3. Caviarder des documents localement :",
    "howto_prot_step3_desc": "Déposez un PDF, Word (.docx) ou une image ci-dessous (jusqu'à 20 Mo, 20 pages par passe). Ajustez les zones ou dessinez-en, puis téléchargez une copie vérifiée.",
    "howto_doc_steps": "1. Cliquez sur une zone d'aperçu pour l'activer ou utilisez Dessiner. 2. Dessinez sur 3+ pages et cliquez sur Apprendre la règle de position. 3. Choisissez le style et cliquez sur Caviarder et télécharger.",
    "tool_save_location": "📍 Apprendre la règle de position",
    "howto_steps_badge": "Étape par étape",
    "howto_logic_step1_title": "1. Assistant de détection personnelle (4 étapes) :",
    "howto_logic_step1_desc": "Cliquez sur + Créer une logique personnelle → Étape 1 : Saisissez 2+ exemples positifs → Étape 2 : Choisissez un modèle proposé → Étape 3 : Testez sur un texte → Étape 4 : Définissez nom, catégorie, confiance et indices de contexte.",
    "howto_logic_step2_title": "2. Règles de position pour documents :",
    "howto_logic_step2_desc": "Dans Document Studio, entourez un champ récurrent sur au moins 3 pages et cliquez sur Apprendre la règle de position.",
    "howto_logic_step3_title": "3. Studio de politiques (Règles DLP par site) :",
    "howto_logic_step3_desc": "Cliquez sur + Créer une règle de site → choisissez un modèle rapide ou saisissez un domaine → sélectionnez la portée et l'action (Bloquer, Caviarder ou Avertir).",
    "howto_audit_badge": "Vérification",
    "howto_rev_step1_title": "1. Télémétrie de protection récente :",
    "howto_rev_step1_desc": "Affiche le cumul des détections, éléments protégés et pages ou documents analysés dans votre journal local.",
    "howto_rev_step2_title": "2. Couverture d'analyse transparente :",
    "howto_rev_step2_desc": "Vert (✓) signifie que tout a été inspecté. Ambre (!) ou Rouge (✕) signale les iframes inter-origines ou médias différés non inspectés.",
