    "howto_protection_title": "📘 Kurzanleitung: Seite scannen & schützen",
    "howto_protection_step1": "1. Wählen Sie ein Compliance-Profil (HIPAA, PCI-DSS, DSGVO) oder aktivieren Sie Kategorien.",
    "howto_protection_step2": "2. Klicken Sie auf Seite scannen (oder Alt+Shift+S), um sichtbaren Text und Bilder zu prüfen.",
    "howto_protection_step3": "3. Prüfen Sie die maskierten Treffer und wenden Sie Masken an oder kopieren Sie geschwärzten Text.",
    "howto_doc_title": "📘 Schritt für Schritt: Dokumente schwärzen",
    "howto_doc_step1": "1. Laden Sie ein PDF (.pdf), Word (.docx) oder Bild (.png, .jpg, .webp) bis 20 MB hoch.",
    "howto_doc_step2": "2. Prüfen Sie die Markierungen auf jeder Seite oder zeichnen Sie mit ✏️ eigene Bereiche.",
    "howto_doc_step3": "3. Schwärzen & Prüfen: Wählen Sie den Stil und klicken Sie auf Schwärzen & Herunterladen.",
    "tool_save_location_rule": "📍 Positionsregel lernen",
    "howto_logic_title": "📘 Schritt für Schritt: Eigene Logik & Website-Richtlinien",
    "howto_logic_step1": "1. Eigene Logik: Klicken Sie auf + Eigene Logik erstellen und fügen Sie 2–5 Beispiele ein.",
    "howto_logic_step2": "2. Testen & Anpassen: Testen Sie das Muster mit Beispieltext, Kontextwörtern und Längen.",
    "howto_logic_step3": "3. Website-Richtlinien: Erstellen Sie Regeln pro Domain zum Blockieren oder Warnen beim Einfügen.",
    "howto_review_title": "📘 Schritt für Schritt: Abdeckung prüfen & Audit exportieren",
    "howto_review_step1": "1. Scan-Abdeckung: Prüfen Sie, ob der Scan vollständig, teilweise oder blockiert war.",
    "howto_review_step2": "2. Letzte Aktivitäten: Jede Aktion wird lokal nur mit Zählern protokolliert.",
