    "contextual_guide_close": "Verstanden",
    "howto_badge": "3 Schritte",
    "howto_prot_step1_title": "1. Webseiten scannen & maskieren (Alt+Shift+S):",
    "howto_prot_step1_desc": "Klicken Sie auf Seite scannen, um 24 Kategorien von PII, PHI, Finanzdaten und Geheimnissen lokal zu erkennen. Prüfen Sie die Ergebnisse und wenden Sie Masken an oder kopieren Sie geschwärzten Text.",
    "howto_prot_step2_title": "2. KI-Prompts & Formulare schützen (Einfüge-Schutzschild):",
    "howto_prot_step2_desc": "Aktiv in diesem Tab nach dem Öffnen von GovernWorld (oder auf allen Websites mit Immer aktiv). Beim Einfügen sensibler Daten in ChatGPT, Claude oder Formulare können Sie bereinigen, unverändert einfügen oder abbrechen.",
    "howto_prot_step3_title": "3. Dokumente lokal schwärzen:",
    "howto_prot_step3_desc": "Legen Sie unten ein PDF, Word (.docx) oder Bild ab (bis 20 MB, 20 Seiten pro Durchgang). Passen Sie Markierungen an und laden Sie eine pixelgeprüfte Kopie herunter.",
    "howto_doc_steps": "1. Klicken Sie auf eine Markierung zum Umschalten oder nutzen Sie Bereich zeichnen. 2. Zeichnen Sie auf 3+ Seiten und klicken Sie auf Positionsregel lernen. 3. Wählen Sie den Stil und klicken Sie auf Schwärzen & Herunterladen.",
    "tool_save_location": "📍 Positionsregel lernen",
    "howto_steps_badge": "Schritt für Schritt",
    "howto_logic_step1_title": "1. Assistent für eigene Erkennungslogik (4 Schritte):",
    "howto_logic_step1_desc": "Klicken Sie auf + Eigene Logik erstellen → Schritt 1: 2+ positive Beispiele eingeben → Schritt 2: Vorgeschlagenes Muster wählen → Schritt 3: Live testen → Schritt 4: Name, Kategorie, Konfidenz und Kontext-Hinweise speichern.",
    "howto_logic_step2_title": "2. Positionsbasierte Dokumentregeln:",
    "howto_logic_step2_desc": "Zeichnen Sie im Document Studio auf mindestens 3 Seiten Rahmen um ein wiederkehrendes Feld und klicken Sie auf Positionsregel lernen.",
    "howto_logic_step3_title": "3. Policy Studio (Website-DLP-Regeln):",
    "howto_logic_step3_desc": "Klicken Sie auf + Website-Richtlinie erstellen → wählen Sie eine Vorlage oder geben Sie eine Domain ein → legen Sie Datenbereich und Aktion (Blockieren, Schwärzen oder Warnen) fest.",
    "howto_audit_badge": "Prüfung",
    "howto_rev_step1_title": "1. Aktuelle Schutz-Telemetrie:",
