    "howto_protection_title": "📘 クイックガイド：ページのスキャンと保護手順",
    "howto_protection_step1": "1. コンプライアンスプリセット（HIPAA、PCI-DSS、GDPR）または24種類の検出カテゴリを選択します。",
    "howto_protection_step2": "2. 「ページをスキャン」（または Alt+Shift+S）をクリックして表示テキストと画像を検査します。",
    "howto_protection_step3": "3. 検出結果を確認し、「選択したマスクを適用」または「墨消し済みテキストをコピー」を実行します。",
    "howto_doc_title": "📘 ステップガイド：ドキュメントの墨消し手順",
    "howto_doc_step1": "1. PDF（.pdf）、Word（.docx）、または画像（.png、.jpg、.webp）ファイル（最大20 MB）を選択します。",
    "howto_doc_step2": "2. 各ページの検出枠を確認・調整し、必要に応じて「✏️ 範囲を描画」で手動枠を追加します。",
    "howto_doc_step3": "3. 墨消しスタイル（黒塗り・白塗り・スタンプ）を選択して「墨消ししてダウンロード」をクリックします。",
    "tool_save_location_rule": "📍 位置ルールを学習",
    "howto_logic_title": "📘 ステップガイド：カスタムロジックとサイトポリシーの作成",
    "howto_logic_step1": "1. カスタムロジック：「+ カスタムロジックを作成」をクリックし、2〜5個のサンプルを入力します。",
    "howto_logic_step2": "2. テストと調整：サンプルテキスト、コンテキストキーワード、文字数制限で精度を確認します。",
    "howto_logic_step3": "3. サイトポリシー：ドメインごとの貼り付けブロックや自動保護ルールを設定します。",
    "howto_review_title": "📘 ステップガイド：カバレッジ確認と署名付き監査ログの出力",
    "howto_review_step1": "1. スキャンカバレッジ：直近のスキャンが完全・部分的・制限付きのいずれかを確認します。",
    "howto_review_step2": "2. 最近のアクティビティ：すべての操作は件数とタイムスタンプのみでローカルに記録されます。",
    "howto_review_step3": "3. 署名付き監査ログ出力：ECDSA P-256署名付きのJSONL監査証跡をダウンロードします。",
    "account_clear_btn": "アカウント連携を解除",
