    "wizard_max_len_label": "最大文字数（任意）",
    "contextual_guide_open_about": "基本情報で全21件のガイドを見る",
    "contextual_guide_close": "閉じる",
    "howto_badge": "3ステップ",
    "howto_prot_step1_title": "1. Webページのスキャンとマスク (Alt+Shift+S):",
    "howto_prot_step1_desc": "「ページをスキャン」をクリックして24カテゴリのPII・医療・金融・機密情報を端末内で検出します。結果を確認し、「選択したマスクを適用」または「墨消し済みテキストをコピー」を実行します。",
    "howto_prot_step2_title": "2. AIプロンプトとフォームの保護 (貼り付けシールド):",
    "howto_prot_step2_desc": "GovernWorldを開いた後のこのタブ（または常時オン設定時は全サイト）で有効です。ChatGPTやClaude等に機密情報を貼り付ける際、墨消しして貼り付け・そのまま貼り付け・キャンセルを選択できます。",
    "howto_prot_step3_title": "3. ドキュメントのローカル墨消し:",
    "howto_prot_step3_desc": "PDF、Word (.docx)、画像をドロップ（最大20 MB、1回20ページまで）。検出枠の調整や範囲描画を行い、ピクセル検証済みの墨消しファイルをダウンロードできます。",
    "howto_doc_steps": "1. サムネイル上の枠をクリックして切り替えるか「範囲を描画」で追加します。 2. 3ページ以上に枠を描画して「位置ルールを学習」をクリックすると再利用ルールを保存できます。 3. スタイルを選んで「墨消ししてダウンロード」をクリックします。",
    "tool_save_location": "📍 位置ルールを学習",
    "howto_steps_badge": "手順ガイド",
    "howto_logic_step1_title": "1. カスタム検出ウィザード (4ステップ):",
    "howto_logic_step1_desc": "「+ カスタムロジックを作成」→ ステップ1: 2件以上のサンプルを入力 → ステップ2: 生成された正規表現を選択 → ステップ3: テスト文字列で検証 → ステップ4: ルール名・カテゴリ・信頼度・コンテキスト語を設定して保存します。",
    "howto_logic_step2_title": "2. ドキュメント位置認識ルール:",
    "howto_logic_step2_desc": "Document Studioで3ページ以上の共通位置（ヘッダーID等）に枠を描き、「位置ルールを学習」をクリックすると座標ルールとして保存されます。",
    "howto_logic_step3_title": "3. ポリシースタジオ (サイト別DLPルール):",
    "howto_logic_step3_desc": "「+ サイトポリシーを作成」→ テンプレート選択またはドメイン入力 → 保護対象データとアクション（ブロック・自動墨消し・警告）を設定します。",
    "howto_audit_badge": "検証・監査",
    "howto_rev_step1_title": "1. 最近の保護テレメトリ:",
    "howto_rev_step1_desc": "ローカル監査ログに基づき、検出件数、保護された項目数、スキャン済みページ・文書数を集計表示します。",
    "howto_rev_step2_title": "2. 正確なスキャンカバレッジ表示:",
    "howto_rev_step2_desc": "緑 (✓) は全領域の検査完了を示します。黄 (!) や赤 (✕) はクロスオリジンiframeや保護メディア等で自動検査できない領域があることを示します。",
    "howto_rev_step3_title": "3. 署名付き監査ログとコンプライアンス証明書:",
    "howto_rev_step3_desc": "「署名付き監査ログをエクスポート」をクリックすると、ECDSA P-256署名付き .jsonl ログと印刷可能な証明書を取得できます。",
    "disconnect_account_btn": "アカウント連携を解除",
    "mgmt_card_title": "エンタープライズ端末登録と署名付きポリシー同期",
    "mgmt_card_desc": "組織のEd25519ポリシーコーディネーターにこのブラウザを登録するか、管理ポリシーを強制同期します。",
