    "howto_protection_title": "📘 Guia Rápido: Como verificar e proteger uma página",
    "howto_protection_step1": "1. Escolha um perfil de conformidade (HIPAA, PCI-DSS, LGPD/GDPR) ou ative qualquer uma das 24 categorias.",
    "howto_protection_step2": "2. Clique em Escanear Página (ou Alt+Shift+S) para inspecionar texto visível, rótulos e imagens.",
    "howto_protection_step3": "3. Revise os itens encontrados e clique em Aplicar máscaras ou Copiar texto censurado.",
    "howto_doc_title": "📘 Passo a passo: Como censurar um documento",
    "howto_doc_step1": "1. Envie ou arraste um PDF (.pdf), Word (.docx) ou imagem (.png, .jpg, .webp) de até 20 MB.",
    "howto_doc_step2": "2. Revise e ajuste as caixas em cada página ou use ✏️ Desenhar Caixa para adicionar regiões manuais.",
    "howto_doc_step3": "3. Censurar e verificar: Escolha o estilo de censura e clique em Censurar e Baixar.",
    "tool_save_location_rule": "📍 Aprender regra de posição",
    "howto_logic_title": "📘 Passo a passo: Como criar lógica personalizada e políticas de site",
    "howto_logic_step1": "1. Lógica pessoal: Clique em + Criar lógica pessoal e cole de 2 a 5 exemplos positivos.",
    "howto_logic_step2": "2. Teste e configure: Teste o padrão com texto de amostra, palavras-chave de contexto e tamanho.",
    "howto_logic_step3": "3. Políticas de site: Adicione regras por domínio para bloquear ou alertar ao colar dados.",
    "howto_review_title": "📘 Passo a passo: Como verificar cobertura e exportar auditoria",
    "howto_review_step1": "1. Cobertura da verificação: Confira se a verificação foi completa, parcial ou bloqueada pelo navegador.",
    "howto_review_step2": "2. Atividade recente: Cada ação é registrada localmente apenas com contagens e horários.",
    "howto_review_step3": "3. Exportar auditoria assinada: Baixe um comprovante JSONL assinado com ECDSA P-256.",
