    "howto_badge": "3 etapas",
    "howto_prot_step1_title": "1. Escanear e mascarar páginas web (Alt+Shift+S):",
    "howto_prot_step1_desc": "Clique em Escanear Página para detectar 24 categorias de PII, PHI, dados financeiros e segredos no dispositivo. Revise os itens e aplique máscaras ou copie o texto censurado.",
    "howto_prot_step2_title": "2. Proteger prompts de IA e formulários (Escudo de Colagem):",
    "howto_prot_step2_desc": "Ativo nesta guia após abrir o GovernWorld (ou em todos os sites com Sempre Ativo). Ao colar dados sensíveis no ChatGPT, Claude ou formulários, sanitize, cole sem alterar ou cancele.",
    "howto_prot_step3_title": "3. Censurar documentos localmente:",
    "howto_prot_step3_desc": "Solte um PDF, Word (.docx) ou imagem abaixo (até 20 MB, 20 páginas por vez). Ajuste as caixas ou desenhe áreas manuais e baixe uma cópia verificada.",
    "howto_doc_steps": "1. Clique em uma caixa na miniatura para alternar ou use Desenhar Caixa. 2. Desenhe caixas em 3+ páginas e clique em Aprender regra de posição. 3. Escolha o estilo e clique em Censurar e Baixar.",
    "tool_save_location": "📍 Aprender regra de posição",
    "howto_steps_badge": "Passo a passo",
    "howto_logic_step1_title": "1. Assistente de detecção pessoal (4 etapas):",
    "howto_logic_step1_desc": "Clique em + Criar lógica pessoal → Etapa 1: Insira 2+ exemplos positivos → Etapa 2: Escolha um padrão sugerido → Etapa 3: Teste ao vivo → Etapa 4: Defina nome, categoria, confiança e dicas de contexto.",
    "howto_logic_step2_title": "2. Regras de posição em documentos:",
    "howto_logic_step2_desc": "No Document Studio, desenhe caixas ao redor de um campo recorrente em pelo menos 3 páginas e clique em Aprender regra de posição.",
    "howto_logic_step3_title": "3. Estúdio de Políticas (Regras DLP por site):",
    "howto_logic_step3_desc": "Clique em + Criar Política de Site → escolha um modelo rápido ou digite um domínio → selecione o escopo e a ação (Bloquear, Auto-censurar ou Alertar).",
    "howto_audit_badge": "Verificação",
    "howto_rev_step1_title": "1. Telemetria de proteção recente:",
    "howto_rev_step1_desc": "Mostra o total acumulado de itens detectados, protegidos e páginas ou documentos verificados no log de auditoria local.",
    "howto_rev_step2_title": "2. Cobertura transparente da verificação:",
    "howto_rev_step2_desc": "Verde (✓) indica inspeção completa. Âmbar (!) ou Vermelho (✕) avisa quando iframes de origem cruzada ou mídias não puderam ser inspecionados.",
    "howto_rev_step3_title": "3. Auditoria assinada e certificado de conformidade:",
    "howto_rev_step3_desc": "Clique em Exportar log de auditoria assinado para baixar o arquivo .jsonl assinado com ECDSA P-256 e o certificado imprimível.",
